const { createClient } = require('@supabase/supabase-js');
const client = createClient('https://rwsradcjrkqroismpwcz.supabase.co', 'sb_publishable_Z_fw9IeN4f_0vSHHDurSQg_sDLiYqMg');

async function testAuth() {
  const email = 'marketer-' + Date.now() + '@cadra-ads-test.com';
  const password = 'CadraPassword2026!';
  console.log('Testing SignUp for:', email);

  const { data: signUpData, error: signUpError } = await client.auth.signUp({
    email,
    password,
    options: {
      data: {
        full_name: 'Studio Test Marketer',
        store_url: 'https://luminarybotanicals.com'
      }
    }
  });

  if (signUpError) {
    console.error('SignUp Error:', signUpError);
    return;
  }

  console.log('SignUp Success! User ID:', signUpData.user?.id);
  console.log('User metadata:', signUpData.user?.user_metadata);
  console.log('Session present (auto-confirmed)?:', !!signUpData.session);

  // If session is present or let's try sign in
  const { data: signInData, error: signInError } = await client.auth.signInWithPassword({
    email,
    password
  });

  if (signInError) {
    console.log('SignIn note (expected if email confirmation is required):', signInError.message);
  } else {
    console.log('SignIn Success! Active session token length:', signInData.session.access_token.length);
  }
}

testAuth();
"

